// Arma el resumen que se manda por correo con lo que expiró (o expiraría, en modo prueba).
const r = $json.data;
const money = (n, c) => (Number(n) || 0).toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' ' + (c || 'MXN');

const lines = r.quotes.map(q =>
  '• ' + q.quote_number + ' — ' + (q.guest_name || 'Sin nombre') + ' — ' + money(q.total, q.currency) + ' (creada ' + String(q.created_at || '').slice(0, 10) + ')'
);

const totals = {};
r.quotes.forEach(q => { totals[q.currency || 'MXN'] = (totals[q.currency || 'MXN'] || 0) + (Number(q.total) || 0); });
const suma = Object.entries(totals).map(([c, v]) => money(v, c)).join('  ·  ');

const cabecera = r.dry_run
  ? 'PRUEBA: no se cambió nada. Estas cotizaciones se marcarían como Vencidas:'
  : 'Se marcaron como Vencidas estas cotizaciones que seguían en borrador:';

let text = cabecera + '\n\n'
  + 'Borradores con más de ' + r.days + ' días: ' + r.processed + '\n'
  + lines.join('\n') + '\n\n'
  + 'Suma de los montos: ' + suma;

if (r.remaining > 0) {
  text += '\n\nQuedan ' + r.remaining + ' por procesar; se tomarán en la siguiente ejecución.';
}
text += '\n\nPuedes verlas en Cotizaciones filtrando por el estado "Vencida".';

return [{ json: {
  subject: (r.dry_run ? '[PRUEBA] ' : '') + 'Cotizaciones en borrador marcadas como vencidas: ' + r.processed,
  text,
} }];

// Una tarea por cada cotizacion que paso a Vencida, para que una persona la revise.
// En modo prueba no se cambia nada, asi que tampoco se crean tareas.
const r = $('Expirar borradores').first().json.data;
if (r.dry_run) return [];
const manana = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
return r.quotes.map(q => ({ json: {
  taskable_type: 'App\Models\Quote',
  taskable_id: q.id,
  title: q.quote_number + ' → Expirada',
  description: 'La cotizacion ' + q.quote_number + ' (' + (q.guest_name || 'Sin nombre') + ', ' + Number(q.total || 0).toLocaleString('es-MX', { minimumFractionDigits: 2 }) + ' ' + (q.currency || 'MXN') + ') llevaba mas de ' + r.days + ' dias en borrador y paso a Vencida. Revisala: si sigue vigente, crea una nueva o dale seguimiento al cliente.',
  due_at: manana,
  status: 'open'
} }));
